import { describe, it } from 'node:test';
import assert from 'node:assert';
import { load, CORE_SCHEMA } from 'js-yaml';

describe('proof', () => {
  it('explicit !!int resolves signed binary literals (core schema)', () => {
    assert.strictEqual(load('!!int "-0b11"', { schema: CORE_SCHEMA }), -3);
    assert.strictEqual(load('!!int "+0b11"', { schema: CORE_SCHEMA }), 3);
    assert.strictEqual(load('!!int "0b11"', { schema: CORE_SCHEMA }), 3);
  });
});

